import sys
input = sys.stdin.read().split()
n = int(input[0])
commands = [(input[i*2], int(input[i*2+1])) for i in range(n)]

result_and = 1023
result_or = 0
result_xor = None

for op, val in commands:
    if op == '&':
        result_and &= val
    elif op == '|':
        result_or |= val
    else:  # op == '^'
        if result_xor is None:
            result_xor = val
        else:
            result_xor ^= val

output = []
if result_and != 1023:
    output.append(f"& {result_and}")
if result_or != 0:
    output.append(f"| {result_or}")
if result_xor is not None:
    output.append(f"^ {result_xor}")

print(len(output))
for line in output:
    print(line)
